INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (108, 354, 'PE CLING FILM (FOOD WRAPPING)', '../upload/image/20181227/20181227132254_83341.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;">PE CLING FILM (FOOD WRAPPING)</span></p> <p><span style="color:#009900;font-family:Verdana;">The product does not contain any plasticizer. It features transparency, tensile strong, very good anti-fog performance. It is ideal for food packaging materials. </span></p> <p><span style="color:#009900;font-family:Verdana;">Thickness :8-15UM</span></p> <p><span style="color:#009900;font-family:Verdana;">Width :300MM,350MM,450MM,500MM</span></p> <p><span style="color:#009900;font-family:Verdana;">Length :30M,50M,60M,100M,120M,150M,200M,500,1500M</span></p> <p><span style="color:#009900;font-family:Verdana;">Inner core:1.5”,1.8”,2”,3”,6”</span></p> <p><span style="color:#009900;font-family:Verdana;">Applications: packaging vegetables, fruit, cooked food. Applies to refrigerators, microwave ovens.</span></p>', '2026-09-06 20:58:45');